import React, { useState, useCallback } from 'react';
import { Calendar, Button, ButtonGroup, Stack } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
  initialDate?: Date;
}

const startOfDay = (d: Date): Date => {
  const copy = new Date(d);
  copy.setHours(0, 0, 0, 0);
  return copy;
};

const addDays = (d: Date, days: number): Date => {
  const copy = new Date(d);
  copy.setDate(copy.getDate() + days);
  return copy;
};

const ReportDatePicker: React.FC<ReportDatePickerProps> = ({
  onChange,
  initialDate,
}) => {
  const [selectedDate, setSelectedDate] = useState<Date>(
    startOfDay(initialDate ?? new Date())
  );

  const handleDateChange = useCallback(
    (date: Date) => {
      const normalized = startOfDay(date);
      setSelectedDate(normalized);
      onChange?.(normalized);
    },
    [onChange]
  );

  const handleQuickSelect = useCallback(
    (offsetDays: number) => {
      handleDateChange(addDays(new Date(), offsetDays));
    },
    [handleDateChange]
  );

  const isQuickSelected = (offsetDays: number): boolean => {
    const target = startOfDay(addDays(new Date(), offsetDays));
    return target.getTime() === selectedDate.getTime();
  };

  return (
    <Stack direction="column" gap="var(--jx-space-sm)">
      <ButtonGroup aria-label="Быстрый выбор даты отчёта">
        <Button
          variant={isQuickSelected(0) ? 'primary' : 'secondary'}
          size="sm"
          onClick={() => handleQuickSelect(0)}
        >
          Сегодня
        </Button>
        <Button
          variant={isQuickSelected(-1) ? 'primary' : 'secondary'}
          size="sm"
          onClick={() => handleQuickSelect(-1)}
        >
          Вчера
        </Button>
        <Button
          variant={isQuickSelected(-7) ? 'primary' : 'secondary'}
          size="sm"
          onClick={() => handleQuickSelect(-7)}
        >
          Неделя назад
        </Button>
      </ButtonGroup>

      <Calendar
        mode="single"
        view="month"
        value={selectedDate}
        onChange={handleDateChange}
        aria-label="Календарь выбора даты отчёта"
      />
    </Stack>
  );
};

export default ReportDatePicker;

